body {
  width: 100%;
  height: 100%;
  background: transparent;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0 !important; /* 徹底去外邊距貼邊 */
}

/* 主卡片容器 */
.calendar-card {
  width: 100%;
  height: 100%;
  background: #ffffff;
  border-radius: 0px !important; /* 嚴格直角 */
  box-shadow: none !important;    /* 無外陰影 */
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  padding-bottom: 8px; /* 給底部裝飾線留空間 */
}

/* 頂部灰色波點橫條 - 已優化為乾淨高級淡灰底色 */
.top-banner {
  width: 100%;
  height: 28%; /* 橫條高度佔比 */
  background-color: #e8ebed; /* 改為更純粹、清透的淡灰色，完美適配全螢幕色系 */
  /* 放大 background-size 並調整平移位置，讓波點變大、變稀疏 */
  background-image: radial-gradient(#ffffff 10%, transparent 11%), 
                    radial-gradient(#ffffff 10%, transparent 11%);
  background-size: 10px 10px;
  background-position: 0 0, 5px 5px;

  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: #4a4a4a; /* 微調深文字顏色，確保在淡灰底色下更精緻 */
  padding: 2px 0;
}

/* 橫條文字樣式 - 加大 line-height 拉開行間距 */
.banner-text {
  font-size: 9px;
  font-weight: bold;
  font-family: Georgia, serif;
  line-height: 1.4;
}
.banner-sub {
  font-size: 8px;
  font-family: Arial, sans-serif;
  transform: scale(0.9);
  line-height: 1.4;
}
.banner-kr {
  font-size: 7px;
  font-family: sans-serif;
  transform: scale(0.85);
  color: #666666;
  line-height: 1.4;
}

/* 下半部主體內容包裝 */
.main-content {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 14px 2px 14px;
}

/* 左側頭像框 */
.avatar-box {
  width: 72px;
  height: 85px; /* 縱向長方形 */
  background-color: #f5f5f5;
  background-size: cover;
  background-position: center;
  border: 1px solid #e8e8e8;
  border-radius: 0px !important;
  /* 徹底去除了黑白灰階濾鏡，保持原本彩色 */
}

/* 中間日曆主體 */
.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  row-gap: 2px;
  column-gap: 6px;
  text-align: center;
  font-family: "Impact", "Arial Black", -apple-system, sans-serif;
}

/* 星期表頭 */
.week-header {
  font-size: 11px;
  font-weight: 900;
  color: #222222;
  width: 16px;
}
/* 星期六、日的紅色標記 */
.week-header.sunday {
  color: #e61a22 !important;
}

/* 日期矩陣（包裹動態日期的容器） */
.days-matrix {
  display: contents; /* 讓子元素直接繼承 grid 佈局 */
}

/* 每個日期格子 */
.day-cell {
  font-size: 10px;
  font-weight: bold;
  color: #666666;
  height: 11px;
  line-height: 11px;
}
.day-cell.empty {
  visibility: hidden;
}
/* 週末普通日期的顏色 */
.day-cell.weekend {
  color: #999999;
}
/* 當前日期的紅色高亮 */
.day-cell.today {
  color: #e61a22 !important;
  font-weight: 900;
}

/* 右側巨大月份 */
.month-huge {
  font-family: "Impact", "Arial Black", sans-serif;
  font-size: 42px;
  font-weight: 900;
  color: #242424;
  letter-spacing: -2px;
  transform: scaleY(1.2); /* 縱向拉伸，還原雜誌字體質感 */
  padding-left: 0px;       /* 拔除左邊距，讓月份往左移 */
  margin-right: 6px;      /* 往左挪動後，在右邊騰出對應的空隙 */
}

/* 底部裝飾線 - 與頂部淡灰完美呼應 */
.bottom-line {
  position: absolute;
  bottom: 6px;
  left: 12px;
