/* 膠囊本體 */
.capsule {
  position: absolute;
  width: 86%;
  height: 46px;
  border-radius: 50px;
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  border: 1.5px solid rgba(255, 255, 255, 0.6);
  box-sizing: border-box;
}

/* 上方膠囊：向上揚 */
.capsule.top {
  top: 22%;
  left: 5%;
  transform: rotate(-5deg);
}

/* 下方膠囊：向下垂，左側剛好相切 */
.capsule.bottom {
  top: 54%;
  left: 8%;
  transform: rotate(5deg);
}

/* 圓形頭像 */
.avatar {
  position: absolute;
  top: 1.5px;
