  flex-direction: column;
  position: relative;
  overflow: hidden;
  padding-bottom: 8px; /* 給底部裝飾線留空間 */
}

/* 頂部灰色波點橫條 - 已優化為乾淨高級淡灰底色 */
.top-banner {
  width: 100%;
  height: 28%; /* 橫條高度佔比 */
