  font-weight: 900;
  color: #242424;
  letter-spacing: -2px;
  transform: scaleY(1.2); /* 縱向拉伸，還原雜誌字體質感 */
  padding-left: 0px;       /* 拔除左邊距，讓月份往左移 */
  margin-right: 6px;      /* 往左挪動後，在右邊騰出對應的空隙 */
