   ============================================================ */

/* ============================================================
   第一部分：顶部导航栏 - 完全透明 + 内容居中
   ============================================================ */

/* ----- 顶部导航栏容器 ----- */
.chat-header-custom {
    /* 完全透明背景 */
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;

    /* 去掉边框 */
    border-bottom: none !important;

    /* 增加高度以容纳更多内容 */
    height: 110px !important;
    min-height: 110px !important;
    padding: 12px 16px 8px 16px !important;

    /* 顶部安全区域 */
    padding-top: calc(12px + env(safe-area-inset-top, 0px)) !important;

    /* 去掉底部分隔线 */
    box-shadow: none !important;
}

/* ----- 让内容垂直居中排列 ----- */
.header-profile-section {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
    width: 100% !important;
    height: 100% !important;
    /* 整体向右移动 */
    transform: translateX(45px) !important;
    /* 让伪元素可以绝对定位 */
    position: relative !important;
}

/* ----- 头像居中 + 放大 ----- */
.header-avatar-container {
    margin: 0 auto 4px auto !important;
    order: -5 !important;

    /* 放大头像 */
    width: 50px !important;
    height: 50px !important;
    flex-shrink: 0 !important;

    /* 单独向左移动 + 往下 */
    transform: translateX(-20px) translateY(10px) !important;

    /* 加一点柔和光晕，不影响原样式 */
    box-shadow: 0 0 20px rgba(255, 255, 255, 0.15), 0 4px 12px rgba(0, 0, 0, 0.06) !important;
    position: relative !important;
    z-index: 1 !important;
}

/* 头像内部的图片也跟随放大 */
.header-avatar-container img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 50% !important;
}

/* ============================================================
   在头像右边新增一个头像（用伪元素）
   ============================================================ */
.header-profile-section::after {
    content: "" !important;
    position: absolute !important;
    /* 定位在原头像的右边，挨着 */
    left: calc(50% + 5px) !important;
    top: 50% !important;
    transform: translateY(-50%) translateY(-25px) !important;
    width: 50px !important;
    height: 50px !important;
    border-radius: 50% !important;
    background-image: url('https://i.postimg.cc/DycRKBL9/image.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    border: none !important;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1) !important;
    z-index: 2 !important;
    pointer-events: auto !important;
    cursor: pointer !important;
}

/* 新头像hover效果 */
.header-profile-section::after:hover {
    transform: translateY(-50%) translateY(15px) scale(1.05) !important;
    transition: transform 0.2s ease !important;
}

