:root {
  /* ============================================================
     转账卡片 - 双方统一透明磨砂（无颜色）
     ============================================================ */

  /* === 通用基础（双方共用） === */
  --transfer-card-bg: rgba(239, 239, 239, 0.18);
  --transfer-card-radius: 16px;
  --transfer-card-shadow: none;
  --transfer-card-border: 1px solid rgba(140, 140, 140, 0.35);
  --transfer-card-backdrop: blur(16px) saturate(160%);

  --transfer-icon-bg: rgba(255, 255, 255, 0.20);
  --transfer-icon-radius: 50%;
