  --transfer-icon-color: rgba(38, 38, 38, 0.5);

  --transfer-amount-color: #262626;
  --transfer-amount-font-size: 18px;
  --transfer-amount-font-weight: 600;

  --transfer-label-color: rgba(38, 38, 38, 0.5);
  --transfer-label-font-size: 12px;

  --transfer-subtitle-color: rgba(38, 38, 38, 0.4);
  --transfer-subtitle-font-size: 11px;

  --transfer-status-color: rgba(38, 38, 38, 0.4);
  --transfer-status-font-size: 11px;

  --transfer-divider-color: rgba(140, 140, 140, 0.2);
  --transfer-padding: 12px 14px;
  --transfer-min-width: 200px;
  --transfer-max-width: 260px;

  /* === 我方转账（沿用通用值） === */
  --transfer-me-card-bg: initial;
  --transfer-me-card-radius: initial;
  --transfer-me-card-shadow: initial;
  --transfer-me-card-border: initial;
  --transfer-me-icon-bg: initial;
  --transfer-me-amount-color: initial;
  --transfer-me-label-color: initial;
  --transfer-me-subtitle-color: initial;
  --transfer-me-status-color: initial;
  --transfer-me-divider-color: initial;

  /* === 对方转账（沿用通用值） === */
  --transfer-them-card-bg: initial;
  --transfer-them-card-radius: initial;
  --transfer-them-card-shadow: initial;
  --transfer-them-card-border: initial;
  --transfer-them-icon-bg: initial;
  --transfer-them-amount-color: initial;
  --transfer-them-label-color: initial;
  --transfer-them-subtitle-color: initial;
  --transfer-them-status-color: initial;
  --transfer-them-divider-color: initial;

  /* ============================================================
     转账三态 - 全部透明磨砂，无颜色区分
     ============================================================ */

  /* === 已完成（透明磨砂，无绿色） === */
  --transfer-success-card-bg: rgba(239, 239, 239, 0.18);
  --transfer-success-card-border: 1px solid rgba(140, 140, 140, 0.35);
  --transfer-success-card-shadow: none;
  --transfer-success-icon-bg: rgba(255, 255, 255, 0.20);
  --transfer-success-icon-color: rgba(38, 38, 38, 0.5);
  --transfer-success-label-color: rgba(38, 38, 38, 0.5);
  --transfer-success-status-color: rgba(38, 38, 38, 0.4);
  --transfer-success-amount-color: #262626;

  /* === 已退回（透明磨砂，无红色） === */
  --transfer-rejected-card-bg: rgba(239, 239, 239, 0.18);
  --transfer-rejected-card-border: 1px solid rgba(140, 140, 140, 0.35);
  --transfer-rejected-card-shadow: none;
  --transfer-rejected-icon-bg: rgba(255, 255, 255, 0.20);
  --transfer-rejected-icon-color: rgba(38, 38, 38, 0.5);
  --transfer-rejected-label-color: rgba(38, 38, 38, 0.5);
  --transfer-rejected-status-color: rgba(38, 38, 38, 0.4);
  --transfer-rejected-amount-color: #262626;

