    height: auto !important;
    border-radius: 8px !important;
}
:root {
    /* 我方通话气泡 - 和气泡me完全统一（浅粉版） */
    --call-bubble-me-bg: linear-gradient(155deg, rgba(255,240,245,0.92) 0%, rgba(255,234,242,0.88) 100%);
    --call-bubble-me-text: #5c403a;
    /* 对方通话气泡 - 和气泡them完全统一 */
    --call-bubble-them-bg: #ffffff;
    --call-bubble-them-text: #1c1c1e;
    /* 通话图标颜色 */
    --call-icon-color: #8e8e93;
}

/* ========== 通话卡片主体 ========== */
.msg-videocall-card,
.msg-videocall-card.missed,
.msg-videocall-card.connected,
.msg-videocall-card.cancelled,
.msg-videocall-card.rejected {
    width: fit-content !important;
    min-width: 0 !important;
    max-width: none !important;
    padding: 9px 14px !important;
    border-radius: 20px !important;
    box-shadow: 0 1px 2px rgba(92,64,58,0.06) !important;
    border: none !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    position: relative !important;
    cursor: default !important;
    background: var(--call-bubble-them-bg) !important;
}

/* 我方通话气泡 - 浅粉 */
.bubble-me-custom .msg-videocall-card,
.msg-me .msg-videocall-card {
    background: var(--call-bubble-me-bg) !important;
}

/* 我方通话气泡：尖角右上角 */
.bubble-me-custom .msg-videocall-card,
.bubble-me-custom .msg-videocall-card.missed,
.bubble-me-custom .msg-videocall-card.connected,
.bubble-me-custom .msg-videocall-card.cancelled,
.bubble-me-custom .msg-videocall-card.rejected,
.msg-me .msg-videocall-card,
.msg-me .msg-videocall-card.missed,
.msg-me .msg-videocall-card.connected,
.msg-me .msg-videocall-card.cancelled,
.msg-me .msg-videocall-card.rejected {
    border-radius: 18px 3px 18px 18px !important;
}

/* 对方通话气泡：尖角左上角 */
.bubble-them-custom .msg-videocall-card,
.bubble-them-custom .msg-videocall-card.missed,
.bubble-them-custom .msg-videocall-card.connected,
.bubble-them-custom .msg-videocall-card.cancelled,
.bubble-them-custom .msg-videocall-card.rejected,
.msg-them .msg-videocall-card,
.msg-them .msg-videocall-card.missed,
.msg-them .msg-videocall-card.connected,
.msg-them .msg-videocall-card.cancelled,
.msg-them .msg-videocall-card.rejected {
    border-radius: 3px 18px 18px 18px !important;
}

/* 我方通话图标 - 深咖色，适配浅粉气泡 */
.bubble-me-custom .msg-videocall-card > div:first-child::before,
.msg-me .msg-videocall-card > div:first-child::before {
    background: rgba(92,64,58,0.82) !important;
}

/* ========== 通话图标 ========== */
.msg-videocall-card > div:first-child {
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    flex-shrink: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 0 !important;
    color: transparent !important;
}

/* 隐藏原生SVG */
.msg-videocall-card > div:first-child svg,
.msg-videocall-card > div:first-child svg * {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
}

/* 用mask画电话图标 */
.msg-videocall-card > div:first-child::before {
    content: "" !important;
    display: block !important;
    width: 18px !important;
    height: 18px !important;
    background: var(--call-icon-color) !important;
    -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='currentColor' d='M20 15.5c-1.25 0-2.45-.2-3.57-.57-.35-.11-.74-.03-1.02.24l-2.2 2.2c-2.83-1.44-5.15-3.75-6.59-6.59l2.2-2.21c.28-.27.36-.66.25-1.01-.37-1.12-.57-2.32-.57-3.57 0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1 0 9.39 7.61 17 17 17 .55 0 1-.45 1-1v-3.5c0-.55-.45-1-1-1z'/></svg>") center / contain no-repeat !important;
    mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='currentColor' d='M20 15.5c-1.25 0-2.45-.2-3.57-.57-.35-.11-.74-.03-1.02.24l-2.2 2.2c-2.83-1.44-5.15-3.75-6.59-6.59l2.2-2.21c.28-.27.36-.66.25-1.01-.37-1.12-.57-2.32-.57-3.57 0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1 0 9.39 7.61 17 17 17 .55 0 1-.45 1-1v-3.5c0-.55-.45-1-1-1z'/></svg>") center / contain no-repeat !important;
}

/* ========== 文字区域 ========== */
.msg-videocall-card > div:nth-child(2) {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    max-width: none !important;
    gap: 4px !important;
    white-space: nowrap !important;
    flex-shrink: 1 !important;
    min-width: 0 !important;
}

/* 主文字（状态） */
.msg-videocall-card > div:nth-child(2) > div:first-child {
    font-weight: var(--font-weight, 400) !important;
    letter-spacing: 0 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    margin: 0 !important;
    font-size: 0 !important;
}

/* 默认状态文字 */
.msg-videocall-card > div:nth-child(2) > div:first-child::before {
    font-size: 16px !important;
    font-weight: var(--font-weight, 400) !important;
    line-height: 1.35 !important;
    content: "通话已结束" !important;
}

/* 我方取消 */
.bubble-me-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.bubble-me-custom .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before {
    content: "已取消" !important;
}

/* 对方取消 */
.bubble-them-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.bubble-them-custom .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before,
.bubble-them-custom .msg-videocall-card.rejected > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.rejected > div:nth-child(2) > div:first-child::before {
    content: "对方已取消" !important;
}

/* 通话接通 - 显示时长 */
.msg-videocall-card.connected > div:nth-child(2) > div:first-child::before {
    content: "通话时长 " !important;
}

/* 我方文字颜色 */
.bubble-me-custom .msg-videocall-card > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card > div:nth-child(2) > div:first-child::before {
    color: var(--call-bubble-me-text) !important;
    -webkit-text-fill-color: var(--call-bubble-me-text) !important;
}

/* 对方文字颜色 */
.bubble-them-custom .msg-videocall-card > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card > div:nth-child(2) > div:first-child::before {
    color: var(--call-bubble-them-text) !important;
    -webkit-text-fill-color: var(--call-bubble-them-text) !important;
}

/* 时长（仅connected状态显示） */
.msg-videocall-card > div:nth-child(2) > div:nth-child(2) {
    display: none !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) {
    display: inline-flex !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: auto !important;
    height: auto !important;
    font-size: 16px !important;
    font-weight: var(--font-weight, 400) !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    gap: 0 !important;
    letter-spacing: 0 !important;
    line-height: 1.35 !important;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
    display: inline !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: auto !important;
    height: auto !important;
    font-size: 16px !important;
}

/* 我方时长颜色 */
.bubble-me-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.bubble-me-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) *,
.msg-me .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.msg-me .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
    color: var(--call-bubble-me-text) !important;
    -webkit-text-fill-color: var(--call-bubble-me-text) !important;
}

/* 对方时长颜色 */
.bubble-them-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.bubble-them-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) *,
.msg-them .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.msg-them .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
    color: var(--call-bubble-them-text) !important;
    -webkit-text-fill-color: var(--call-bubble-them-text) !important;
}

/* 隐藏多余元素 */
.msg-videocall-card > div:nth-child(3),
.msg-videocall-card > div:nth-child(3) * {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
}

/* ========== 隐藏双方头像（mynd风格） ========== */
.msg-avatar,
.msg-avatar img,
.msg-avatar-container,
.msg-avatar-container img,
.msg-sender-avatar,
.msg-sender-avatar img,
.msg-receiver-avatar,
.msg-receiver-avatar img,
.avatar-container,
.avatar-container img,
.msg-header-avatar,
.msg-header-avatar img,
.sender-avatar,
.receiver-avatar,
.chat-avatar,
.chat-avatar img,
.msg-avatar-wrapper,
.msg-avatar-wrapper img,
.avatar,
.avatar img,
.avatar-img,
.msg-user-avatar,
.msg-user-avatar img {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
    opacity: 0 !important;
    visibility: hidden !important;
}

/* 消息行去掉头像占位空间 */
.msg-bubble-wrapper:has(.msg-avatar),
.msg-bubble-wrapper:has(.msg-avatar-container),
.msg-bubble-wrapper:has(.avatar-container),
.msg-bubble-wrapper:has(.avatar),
.msg-bubble-wrapper:has(.sender-avatar),
.msg-bubble-wrapper:has(.receiver-avatar),
.msg-bubble-wrapper:has(.msg-user-avatar) {
    grid-template-columns: 1fr !important;
    padding-left: 0 !important;
}

/* 我方消息去掉头像后的右边距调整 */
.msg-bubble-wrapper:has(.bubble-me-custom) {
    margin-right: 0 !important;
}

/* 对方消息去掉头像后的左边距调整 */
.msg-bubble-wrapper:has(.bubble-them-custom) {
    margin-left: 0 !important;
}

/* 仿微信日间 by water */
/* 感谢隱形線帮我找出了bug亚米亚米 */
/* 感谢砂砂老师提供的美化代码๑⁃̀⩊⁃́๑ */
/* 可以修改的地方用🩵标注啦 可以自己调适配 禁止二传 二改自用 */

/* ========================================= 【可直接调整区】底栏按钮位置与大小 ========================================= */
:root {
  /* --- 🩵底栏基础高度 --- */
  --chat-bottom-height: 60px;

  /* --- 🩵输入框 --- */
  --input-box-width: 240px;
  --input-box-height: 36px;
  --input-box-top: 10px;
  --input-box-left: 50px;
  --input-text-color: #1a1a1a;

  /* --- 🩵语音按钮（输入框内右侧） --- */
  --mic-width: 24px;
  --mic-height: 24px;
  --mic-top: 10px;
  --mic-right: 106px;

  /* --- 🩵表情按钮 --- */
  --sticker-width: 22px;
  --sticker-height: 22px;
  --sticker-top: 10px;
  --sticker-left: 298px;

  /* --- 🩵菜单/加号按钮 --- */
  --plus-width: 34px;
  --plus-height: 36px;
  --plus-top: 11px;
  --plus-left: 10px;

  /* --- 🩵AI等待回复按钮 --- */
  --ai-width: 38px;
  --ai-height: 38px;
  --ai-top: 8px;
  --ai-left: 340px;

  /* --- 🩵发送按钮（打字时显示） --- */
  --send-width: 60px;
  --send-height: 60px;
  --send-top: -7px;
  --send-left: 330px;

  /* --- 🩵打字时发送键左侧装饰图（仅装饰） --- */
  --dec-width: 35px;
  --dec-height: 35px;
  --dec-top: 12px;
  --dec-left: 295px;
}

/* ========================================= 仿微信顶栏 (Header) 深度定制 ========================================= */

.chat-header-custom {
  background-color: rgba(237, 237, 237, 0.85) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-bottom: 0.8px solid #d5d5d5 !important;
  border-top: none !important;
  border-left: none !important;
  border-right: none !important;
  height: 50px !important; /* 顶栏高度🩵 */
  min-height: 50px !important;
}

.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  margin-top: 0px !important; /* 🩵备注位置 */
  margin-left: 0px !important;
  justify-content: center !important;
  pointer-events: none !important;
}

.header-avatar-container,
.chat-header-subtitle {
  display: none !important;
}

.header-btn-back svg {
  display: none !important;
}
.header-btn-back {
  background-image: url("https://i.postimg.cc/s2fwKbb1/无标题183_20260222182046.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 20px !important;
  height: 20px !important;
  position: relative !important;
  top: 0px !important;
  left: 4px !important;
  background-color: transparent !important;
  border: none !important;
}

.header-action-btn svg {
  opacity: 0 !important;
}

.header-action-btn:last-child {
  background-image: url("https://i.postimg.cc/W49SyXPw/无标题183_20260222181830.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important;
  height: 24px !important;
  min-width: 24px !important;
  position: relative !important;
  top: 0px !important;
  right: 2px !important;
  background-color: transparent !important;
}

.chat-header-actions {
  gap: 12px !important;
  padding-right: 12px !important;
}

/* ========================================= 底栏背景与分割线 ========================================= */
.input-area-custom {
  background-color: rgba(247, 247, 247, 0.85) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-top: 0.8px solid #dedede !important;
  border-bottom: none !important;
  border-left: none !important;
  border-right: none !important;
  min-height: var(--chat-bottom-height) !important;
  box-shadow: none !important;
  position: relative !important;
}

.input-action-bar-custom,
.input-row-wrapper {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* ========================================= 输入框本体 ========================================= */
textarea.input-box-custom,
.input-box-custom {
  width: var(--input-box-width) !important;
  height: var(--input-box-height) !important;
  min-height: var(--input-box-height) !important;
  background: #ffffff !important;
  background-color: #ffffff !important;
  box-shadow: inset 0 0 0 9999px #ffffff !important;
  border-radius: 6px !important;
  border: none !important;
  position: absolute !important;
  top: var(--input-box-top) !important;
  left: var(--input-box-left) !important;
  padding: 8px 36px 8px 10px !important;
  color: var(--input-text-color) !important;
  -webkit-text-fill-color: var(--input-text-color) !important;
  font-size: 15px !important;
  box-sizing: border-box !important;
  z-index: 20 !important;
}

textarea.input-box-custom::placeholder,
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}

/* ========================================= 独立按钮替换与排版 (已修复菜单消失) ========================================= */

/* 1. 语音按钮 */
.input-btn-mic svg {
  display: none !important;
}
.input-btn-mic {
  width: var(--mic-width) !important;
  height: var(--mic-height) !important;
  position: absolute !important;
  top: var(--mic-top) !important;
  right: var(--mic-right) !important;
  background-image: url("https://i.postimg.cc/mgSGPfQy/无标题183_20260222183226.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 30 !important;
  transform: scale(0.6) !important;
  opacity: 1 !important; /* 强制显示 */
  display: block !important;
}

/* 2. 表情按钮 */
.input-btn-sticker svg {
  display: none !important;
}
.input-btn-sticker {
  width: var(--sticker-width) !important;
  height: var(--sticker-height) !important;
  position: absolute !important;
  top: var(--sticker-top) !important;
  left: var(--sticker-left) !important;
  background-image: url("https://i.postimg.cc/yNYC9QPg/无标题183_20260222183223.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 30 !important;
  opacity: 1 !important; /* 强制显示 */
  display: block !important;
}

/* 3. 菜单/加号按钮 (【核心修复】解除隐身术) */
.input-btn-plus svg {
  display: none !important;
}
.input-btn-plus {
  width: var(--plus-width) !important;
  height: var(--plus-height) !important;
  position: absolute !important;
  top: var(--plus-top) !important;
  left: var(--plus-left) !important;
  background-image: url("https://i.postimg.cc/P5MkCsmM/无标题183_20260222183224.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  z-index: 60 !important;
  opacity: 1 !important; /* 洗掉 icity 里的 opacity:0 */
  visibility: visible !important;
  display: block !important;
}

/* 4. 等待回复 (AI) 按钮 */
.input-btn-ai svg {
  display: none !important;
}
.input-btn-ai {
  width: var(--ai-width) !important;
  height: var(--ai-height) !important;
  min-width: var(--ai-width) !important;
  position: absolute !important;
  top: var(--ai-top) !important;
  left: var(--ai-left) !important;
  background-image: url("https://i.postimg.cc/cLcNvyQn/无标题183_20260222183221.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  opacity: 1 !important;
  z-index: 51 !important;
  transition: opacity 0.2s !important;
  display: block !important;
}

/* 5. 发送按钮 */
.send-btn-custom svg {
  display: none !important;
}
.send-btn-custom {
  width: var(--send-width) !important;
  height: var(--send-height) !important;
  min-width: var(--send-width) !important;
  position: absolute !important;
  top: var(--send-top) !important;
  left: var(--send-left) !important;
  background-image: url("https://i.postimg.cc/7h4RCvXH/wu-biao-ti278-20260320120134.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  z-index: 50 !important;
  opacity: 1 !important;
  display: block !important;
}

/* 打字时 发送键左侧装饰图 */
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))::before {
  content: "" !important;
  position: absolute !important;
  width: var(--dec-width) !important;
  height: var(--dec-height) !important;
  top: var(--dec-top) !important;
  left: var(--dec-left) !important;
  background-image: url("https://i.postimg.cc/yNYC9QPg/无标题183_20260222183223.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  pointer-events: none !important;
  z-index: 40 !important;
}

/* 防卡死补丁 */
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))
  .input-btn-ai {
  opacity: 0 !important;
  pointer-events: none !important;
}
.more-options-popup {
  z-index: 999999 !important;
}
.input-area-custom:has(.more-options-popup) .input-btn-ai,
.input-area-custom:has(.more-options-popup) .input-btn-plus,
.input-area-custom:has(.more-options-popup) .input-btn-sticker,
.input-area-custom:has(.more-options-popup) .input-btn-mic,
.input-area-custom:has(.more-options-popup) .send-btn-custom {
  pointer-events: none !important;
}

/* ========================================= 【修正】系统时间、系统提示框 (解决太长的问题) ========================================= */
.timestamp-custom,
.date-divider-custom,
.system-message-custom,
[class*="system-message"],
[class*="timestamp"],
[class*="date-divider"] {
  width: fit-content !important; /* 像微信一样紧贴文字宽度 */
  max-width: 80% !important;
  margin: 8px auto !important; /* 绝对居中 */

  background-color: #fcfcfc !important;
  border: 0.6px solid #e3e3e3 !important;
  color: #727272 !important;
  border-radius: 6px !important;
  padding: 2px 10px !important;

  display: block !important;
  text-align: center !important;
  box-sizing: border-box !important;
  font-size: 12px !important;
}
/* ========================================= 【可直接调整区】气泡小角 (带弧度三角) 设置 ========================================= */
:root {
  /* --- 我方气泡小角 (右侧绿色) --- */
  --me-tail-size: 9px; /* 决定小角的整体大小 */
  --me-tail-radius: 1.5px; /* 顶尖的圆角弧度 (您要求的4px) */
  --me-tail-top: 14px; /* 上下位置 */
  --me-tail-right: -4px; /* 左右位置 (负数代表往气泡外面移) */

  /* --- AI气泡小角 (左侧白色) --- */
  --them-tail-size: 9px; /* 决定小角的整体大小 */
  --them-tail-radius: 1.5px; /* 顶尖的圆角弧度 (您要求的4px) */
  --them-tail-top: 14px; /* 上下位置 */
  --them-tail-left: -4px; /* 左右位置 (负数代表往气泡外面移) */
}

/* ========================================= 1. 我方气泡 (绿色) ========================================= */
.bubble-me-custom {
  background-color: #95ec69 !important;
  background: #95ec69 !important;

  /* 更改后的内边距和圆角 */
  padding: 8px 12px !important;
  border-radius: 4px !important;

  position: relative !important;
  overflow: visible !important; /* 必须开启，允许小角溢出 */
  box-shadow: none !important;
  border: none !important;
  z-index: 1 !important; /* 建立层级，防止小角被背景吞掉 */
}

/* 强制我方气泡连发时不改变圆角 */
.bubble-me-custom.first,
.bubble-me-custom.mid,
.bubble-me-custom.last {
  border-radius: 4px !important;
}

/* 强制我方气泡内的文字颜色 */
.bubble-me-custom,
.bubble-me-custom * {
  color: #0f180a !important;
}

/* 我方气泡右侧小角 (带弧度的旋转正方形实现) */
.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  top: var(--me-tail-top) !important;
  right: var(--me-tail-right) !important;
  width: var(--me-tail-size) !important;
  height: var(--me-tail-size) !important;
  background-color: #95ec69 !important;

  /* 核心：倒角4px，并旋转45度，让右上角变成向右指的圆润尖角 */
  border-radius: var(--me-tail-radius) !important;
  transform: rotate(45deg) !important;
  -webkit-transform: rotate(45deg) !important;
  z-index: -1 !important; /* 放在气泡底层，无缝融合 */
}

/* ========================================= 2. AI / 对方气泡 (白色) ========================================= */
.bubble-them-custom {
  background-color: #ffffff !important;
  background: #ffffff !important;

  /* 更改后的内边距和圆角 */
  padding: 8px 12px !important;
  border-radius: 4px !important;

  position: relative !important;
  overflow: visible !important;
  box-shadow: none !important;
  border: none !important;
  z-index: 1 !important;
}

/* 强制对方气泡连发时不改变圆角 */
.bubble-them-custom.first,
.bubble-them-custom.mid,
.bubble-them-custom.last {
  border-radius: 4px !important;
}

/* 强制对方气泡内的文字颜色 */
.bubble-them-custom,
.bubble-them-custom * {
  color: #1a1a1a !important;
}

/* AI气泡左侧小角 (带弧度的旋转正方形实现) */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  top: var(--them-tail-top) !important;
  left: var(--them-tail-left) !important;
  width: var(--them-tail-size) !important;
  height: var(--them-tail-size) !important;
  background-color: #ffffff !important;

  /* 核心：倒角4px，并旋转45度，让左下角变成向左指的圆润尖角 */
  border-radius: var(--them-tail-radius) !important;
  transform: rotate(45deg) !important;
  -webkit-transform: rotate(45deg) !important;
  z-index: -1 !important; /* 放在气泡底层，无缝融合 */
}
/* ========================================= 3. 特殊消息自动隐藏气泡与小角 (表情包/图片/转账等) ========================================= */

/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  ),
.bubble-them-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  ) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}

/* 强制隐藏我方特殊消息的气泡小角 */
.bubble-me-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  )::after {
  display: none !important;
}

/* 强制隐藏对方特殊消息的气泡小角 */
.bubble-them-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  )::before {
  display: none !important;
}

/*全屏清透雾化iMessage风_糯叽机聊天页面美化
制作者：面面冰  🐰🤍🩶🖤
🐰信息全屏穿透无遮挡、顶栏渐雾化、底栏沉浸式输入箭头美化🖤🩶🤍
⚠️糯叽馆首发🆘严禁二传至别的饭馆❗️🚫❗️
🌸 浅粉配色版：浅粉气泡 + 深梅子色字体（近黑带粉暖调）
