}

/* 我方文字颜色 */
.bubble-me-custom .msg-videocall-card > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card > div:nth-child(2) > div:first-child::before {
    color: var(--call-bubble-me-text) !important;
    -webkit-text-fill-color: var(--call-bubble-me-text) !important;
}

/* 对方文字颜色 */
.bubble-them-custom .msg-videocall-card > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card > div:nth-child(2) > div:first-child::before {
    color: var(--call-bubble-them-text) !important;
    -webkit-text-fill-color: var(--call-bubble-them-text) !important;
}

/* 时长（仅connected状态显示） */
.msg-videocall-card > div:nth-child(2) > div:nth-child(2) {
    display: none !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) {
    display: inline-flex !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: auto !important;
    height: auto !important;
    font-size: 16px !important;
    font-weight: var(--font-weight, 400) !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    gap: 0 !important;
    letter-spacing: 0 !important;
    line-height: 1.35 !important;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
    display: inline !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: auto !important;
    height: auto !important;
    font-size: 16px !important;
}

/* 我方时长颜色 */
.bubble-me-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.bubble-me-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) *,
.msg-me .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.msg-me .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
    color: var(--call-bubble-me-text) !important;
    -webkit-text-fill-color: var(--call-bubble-me-text) !important;
}

/* 对方时长颜色 */
.bubble-them-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.bubble-them-custom .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) *,
.msg-them .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2),
.msg-them .msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
    color: var(--call-bubble-them-text) !important;
    -webkit-text-fill-color: var(--call-bubble-them-text) !important;
}

/* 隐藏多余元素 */
.msg-videocall-card > div:nth-child(3),
.msg-videocall-card > div:nth-child(3) * {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
}

/* ========== 隐藏双方头像（mynd风格） ========== */
.msg-avatar,
.msg-avatar img,
.msg-avatar-container,
.msg-avatar-container img,
.msg-sender-avatar,
.msg-sender-avatar img,
.msg-receiver-avatar,
.msg-receiver-avatar img,
.avatar-container,
.avatar-container img,
.msg-header-avatar,
.msg-header-avatar img,
.sender-avatar,
.receiver-avatar,
.chat-avatar,
.chat-avatar img,
.msg-avatar-wrapper,
.msg-avatar-wrapper img,
.avatar,
.avatar img,
.avatar-img,
.msg-user-avatar,
.msg-user-avatar img {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
    opacity: 0 !important;
    visibility: hidden !important;
}

/* 消息行去掉头像占位空间 */
.msg-bubble-wrapper:has(.msg-avatar),
.msg-bubble-wrapper:has(.msg-avatar-container),
.msg-bubble-wrapper:has(.avatar-container),
.msg-bubble-wrapper:has(.avatar),
.msg-bubble-wrapper:has(.sender-avatar),
.msg-bubble-wrapper:has(.receiver-avatar),
.msg-bubble-wrapper:has(.msg-user-avatar) {
    grid-template-columns: 1fr !important;
    padding-left: 0 !important;
}

/* 我方消息去掉头像后的右边距调整 */
.msg-bubble-wrapper:has(.bubble-me-custom) {
    margin-right: 0 !important;
}

/* 对方消息去掉头像后的左边距调整 */
.msg-bubble-wrapper:has(.bubble-them-custom) {
    margin-left: 0 !important;
}

/*全屏清透雾化iMessage风_糯叽机聊天页面美化
制作者：面面冰  🐰🤍🩶🖤
🐰信息全屏穿透无遮挡、顶栏渐雾化、底栏沉浸式输入箭头美化🖤🩶🤍
⚠️糯叽馆首发🆘严禁二传至别的饭馆❗️🚫❗️
🌸 浅粉配色版：浅粉气泡 + 深梅子色字体（近黑带粉暖调）
*/
:root {
   /* ========================================
      【顶部导航栏】
      ======================================== */
   --chat-header-bg: transparent;
   --chat-header-border: transparent;
   --chat-header-title-color: #1c1c1e;
   --chat-header-title-size: 17px;
   --chat-header-title-weight: 600;
   --chat-header-subtitle-color: #8e8e93;
   --chat-header-subtitle-size: 11px;
   --chat-header-icon-color: #1c1c1e;
   --chat-header-height: auto;

   /* ========================================
      【未读小红点/数字徽章】
      ======================================== */
   --unread-bg: #ff3b30;
   --chat-header-unread-bg: #ff3b30;
   --chat-header-unread-size: 8px;
   --chat-header-unread-border: 2px solid #f2f2f7;
   --chat-header-unread-num-bg: #ff3b30;
   --chat-header-unread-num-color: #fff;

   /* ========================================
      【时间戳/日期/旁白/系统消息】
      ======================================== */
   --timestamp-color: #8e8e93;
   --date-divider-color: #8e8e93;
   --narration-color: #8e8e93;
   --system-msg-color: #8e8e93;
   --na-bg: transparent;
   --na-bd: none;

   /* ========================================
      【翻译内容】
      ======================================== */
   --trans-detached-bg: #ffffff;
   --trans-detached-color: #1c1c1e;
   --trans-btn1: #c7c7cc;
   --translation-size: 14px;
   --translation-text-color: #8e8e93;
   --translation-line-height: 1.4;
   --translation-bg: transparent;
   --translation-padding: 0;
   --translation-radius: 0;

   /* ========================================
      【回复预览栏（输入框上方）】
      ======================================== */
   --reply-bar-accent: #8e8e93;
   --reply-bar-text-color: #8e8e93;

   --reply-detached-bg: rgba(0,0,0,0.04);
   --reply-detached-radius: 10px;
   --reply-detached-padding: 6px 10px;
   --reply-detached-border: none;
   --reply-detached-text-color: #8e8e93;
   --reply-detached-name-color: #007aff;
   --reply-detached-max-width: 100%;
   --reply-detached-margin-top: 4px;

   /* ========================================
      【我方消息气泡】🌸 浅粉版
      浅粉渐变 + 深梅子色字体（近黑、带粉暖调）
      ======================================== */
   --bubble-me-bg: linear-gradient(155deg, rgba(255,240,245,0.92) 0%, rgba(255,234,242,0.88) 100%);
   --bubble-me-bg-gradient: initial;
   --bubble-me-color: #5c403a;
   --bubble-me-font-size: 16px;
   --bubble-me-line-height: 1.35;
   --bubble-me-padding: 9px 14px;
   --bubble-me-radius: 20px;
   --bubble-me-shadow: 0 1px 2px rgba(92,64,58,0.06);
   --bubble-me-border: none;
   --bubble-me-link-color: #c2185b;
   --bubble-me-backdrop: none;

   /* mynd风格：我方尖角统一右上角 */
   --bubble-me-radius-first: 6px 20px 20px 20px;
   --bubble-me-radius-mid: 6px 20px 20px 20px;
   --bubble-me-radius-last: 6px 20px 20px 20px;

   /* ========================================
      【对方消息气泡】
      ======================================== */
   --bubble-them-bg: #FFFFFF;
   --bubble-them-bg-gradient: initial;
   --bubble-them-color: #1c1c1e;
   --bubble-them-font-size: 16px;
   --bubble-them-line-height: 1.35;
   --bubble-them-padding: 9px 14px;
   --bubble-them-radius: 20px;
   --bubble-them-shadow:none;
   --bubble-them-border:none;
   --bubble-them-link-color: #007aff;
   --bubble-them-backdrop: none;

   /* mynd风格：对方尖角统一左上角 */
   --bubble-them-radius-first: 20px 6px 20px 20px;
   --bubble-them-radius-mid: 20px 6px 20px 20px;
   --bubble-them-radius-last: 20px 6px 20px 20px;

   /* ========================================
      【语音消息】
      我方波形适配浅粉气泡：深梅子色波形
      ======================================== */
   --voice-transcription-color: #8e8e93;
   --voice-transcription-bg: transparent;
   --voice-container-gap: 3px;
   --voice-controls-gap: 0px;
   --voice-play-btn-size: 24px;
   --voice-play-btn-bg: transparent;
   --voice-play-btn-border: none;
   --voice-play-btn-radius: 50%;
   --voice-waveform-height: 24px;
   --voice-waveform-gap: 2px;
   --voice-bar-min-width: 2px;
   --voice-bar-max-width: 3px;
   --voice-bar-radius: 2px;
   --voice-duration-size: 12px;
   --voice-me-bar-active: #5c403a;
   --voice-me-bar-inactive: rgba(92,64,58,0.22);
   --voice-them-bar-active: #1c1c1e;
   --voice-them-bar-inactive: rgba(0,0,0,0.2);

   /* ========================================
      【底部输入区域】
      ======================================== */
   --input-area-bg: transparent;
   --input-area-blur: 0px;
   --input-area-border-top: transparent;
   --input-area-padding: 8px 8px 30px;

   /* ========================================
      【输入框胶囊】
      ======================================== */
   --input-box-bg: transparent;
   --input-box-color: #1c1c1e;
   --input-box-placeholder: #8e8e93;
   --input-box-radius: 22px;
   --input-box-padding: 9px 16px;
   --input-box-font-size: 16px;
   --input-box-border: none;
   --input-box-blur: none;
   --input-box-shadow: none;
   --input-caret-color: #007aff;

   /* ========================================
      【底栏按钮图标】
      ======================================== */
   --icon-img-1: none;
   --icon-img-2: none;
   --icon-img-3: none;
   --icon-img-4: none;

   --plus-btn-bg: transparent;
   --input-btn-plus-bg: transparent;

   /* ========================================
      【发送按钮】
      ======================================== */
   --send-btn-bg: #fffecf2;
   --send-btn-color: #fdb2c7;
   --send-btn-shadow: 0 2px 8px rgba(253,178,199,0.4);

   /* ========================================
      【更多功能面板】
      ======================================== */
   --more-options-bg: rgba(255,255,255,0.9);
   --more-options-blur: blur(30px) saturate(180%);
   --more-options-shadow: 0 -10px 40px rgba(0,0,0,0.1);
   --more-options-border: none;
   --more-options-color: #1c1c1e;
   --more-options-divider: rgba(0,0,0,0.06);

   /* ========================================
      【打字指示器】
      ======================================== */
   --typing-bg: #ffffff;
   --typing-radius: 18px;
   --typing-dot-size: 6px;
   --typing-dot-color: #8e8e93;

   /* ========================================
      【已读状态文字】
      ======================================== */
   --status-color: #8e8e93;
   --status-size: 10px;
   --status-opacity: 0.8;
   --status-read-color: #8e8e93;
}


/* ============================================
   以下是额外样式调整（直接改类名）by面面冰🐰
   ============================================ */

/* ========== 顶部导航栏 ========== */
.glass-header {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 100 !important;
    box-shadow: none !important;
    padding-top: 50px !important;
    padding-bottom: 8px !important;
    background: linear-gradient(to bottom,
        rgba(242,242,247,1) 0%,
        rgba(242,242,247,0.85) 20%,
