:root {
    /* ===== 全局 — 微博浅灰背景 ===== */
    --forum-page-bg: #f5f5f5;
    --forum-page-bg-image: none;
    --forum-page-bg-size: auto;
    --forum-page-bg-position: center;
    --forum-page-bg-repeat: no-repeat;
    --forum-page-bg-attachment: fixed;
    --forum-text: #333333;
    --forum-text-muted: #999999;
    --forum-link: #eb7350;
    --forum-accent: #ff8200;
    --forum-divider: #ececec;

    /* ===== 顶栏 — 微博橙红渐变 ===== */
    --forum-chrome-bg: #ff8200;
    --forum-chrome-bg-image: linear-gradient(135deg, #ffb347 0%, #ff8200 50%, #f25c54 100%);
    --forum-chrome-bg-size: 100% 100%;
    --forum-chrome-bg-position: center;
    --forum-chrome-shadow: 0 2px 6px rgba(242, 92, 84, 0.25);
    --forum-chrome-border: none;
    --forum-chrome-backdrop-filter: none;
    --forum-chrome-title-color: #ffffff;
    --forum-chrome-title-size: 18px;
    --forum-chrome-title-weight: 700;
    --forum-chrome-title-letter-spacing: 0.5px;
    --forum-chrome-title-text-shadow: 0 1px 2px rgba(0,0,0,0.15);
    --forum-chrome-icon-color: #ffffff;
    --forum-chrome-icon-bg: rgba(255,255,255,0.18);
    --forum-chrome-icon-radius: 50%;

    /* ===== 底栏 — 微博白色底栏带橙色高亮 ===== */
    --forum-chrome-nav-bg: #ffffff;
    --forum-chrome-nav-bg-image: none;
    --forum-chrome-nav-shadow: 0 -1px 0 #ececec, 0 -2px 10px rgba(0,0,0,0.04);
    --forum-chrome-nav-border: none;
    --forum-chrome-nav-radius: 0;
    --forum-chrome-nav-backdrop-filter: none;
    --forum-chrome-nav-active: #ff8200;
    --forum-chrome-nav-active-bg: transparent;
    --forum-chrome-nav-active-transform: none;
    --forum-chrome-nav-inactive: #999999;
    --forum-chrome-nav-label-size: 10px;
    --forum-chrome-nav-label-weight: 500;

    /* ===== FAB — 微博橙色发布按钮 ===== */
    --forum-chrome-fab-bg: linear-gradient(135deg, #ffb347 0%, #ff8200 60%, #f25c54 100%);
    --forum-chrome-fab-bg-image: none;
    --forum-chrome-fab-color: #ffffff;
    --forum-chrome-fab-shadow: 0 4px 12px rgba(255,130,0,0.5), 0 2px 4px rgba(242,92,84,0.3);
    --forum-chrome-fab-radius: 50%;
    --forum-chrome-fab-border: 3px solid #ffffff;
    --forum-chrome-fab-transform: translateY(-8px);
    --forum-chrome-fab-icon-url: none;
    --forum-chrome-fab-icon-size: 22px;

    /* ===== 帖子卡片 — 微博白色卡片 ===== */
    --forum-post-bg: #ffffff;
    --forum-post-bg-image: none;
    --forum-post-bg-size: auto;
    --forum-post-bg-position: center;
    --forum-post-border: none;
    --forum-post-border-left: none;
    --forum-post-radius: 10px;
    --forum-post-shadow: 0 1px 3px rgba(0,0,0,0.04);
    --forum-post-backdrop-filter: none;

    /* ===== 帖子文字 ===== */
    --forum-post-title-color: #333333;
    --forum-post-title-size: 16px;
    --forum-post-title-weight: 700;
    --forum-post-title-letter-spacing: 0;
    --forum-post-title-text-shadow: none;
    --forum-post-title-line-height: 1.4;
    --forum-post-excerpt-color: #555555;
    --forum-post-excerpt-size: 15px;
    --forum-post-excerpt-line-height: 1.6;
    --forum-post-board-tag-bg: #fff4e6;
    --forum-post-board-tag-color: #ff8200;
    --forum-post-board-tag-radius: 4px;
    --forum-post-board-tag-padding: 2px 8px;
    --forum-post-board-tag-size: 12px;
    --forum-post-board-tag-weight: 600;
    --forum-post-board-tag-border: 1px solid #ffd9b3;
    --forum-post-time-color: #999999;
    --forum-post-author-color: #eb7350;
    --forum-post-author-weight: 600;
    --forum-post-avatar-radius: 50%;
    --forum-post-avatar-border: none;
    --forum-post-avatar-ring: 0 0 0 2px #ffffff, 0 1px 4px rgba(0,0,0,0.1);
    --forum-post-thumb-radius: 6px;
    --forum-post-metric-num-color: #ff8200;
    --forum-post-metric-num-weight: 700;
    --forum-post-metric-num-size: 16px;
    --forum-post-metric-label-color: #999999;

    /* ===== 板块 ===== */
    --forum-board-card-bg: #ffffff;
    --forum-board-card-bg-image: none;
    --forum-board-card-radius: 10px;
    --forum-board-card-border: none;
    --forum-board-card-shadow: 0 1px 3px rgba(0,0,0,0.04);
    --forum-board-card-padding: 14px;
    --forum-board-icon-bg: linear-gradient(135deg, #ffb347, #ff8200);
    --forum-board-icon-radius: 10px;
    --forum-board-icon-size: 44px;
    --forum-board-name-color: #333333;
    --forum-board-name-size: 15px;
    --forum-board-name-weight: 600;
    --forum-board-desc-color: #999999;
    --forum-board-desc-size: 12px;
    --forum-board-hero-bg: linear-gradient(135deg, #ffb347 0%, #ff8200 50%, #f25c54 100%);
    --forum-board-hero-bg-image: none;
    --forum-board-hero-min-height: 110px;
    --forum-board-hero-padding: 22px 16px;
    --forum-board-hero-title-color: #ffffff;
    --forum-board-hero-title-size: 20px;
    --forum-board-hero-title-weight: 700;
    --forum-board-hero-desc-color: rgba(255,255,255,0.9);
    --forum-board-cover-radius: 10px;

    /* ===== 个人页 ===== */
    --forum-profile-bg: #f5f5f5;
    --forum-profile-bg-image: none;
    --forum-profile-header-bg: linear-gradient(135deg, #ffb347 0%, #ff8200 50%, #f25c54 100%);
    --forum-profile-header-bg-image: none;
    --forum-profile-header-padding: 26px 16px;
    --forum-profile-avatar-size: 72px;
    --forum-profile-avatar-radius: 50%;
    --forum-profile-avatar-border: 3px solid #ffffff;
    --forum-profile-avatar-ring: 0 2px 8px rgba(0,0,0,0.15);
    --forum-profile-name-color: #ffffff;
    --forum-profile-name-size: 19px;
    --forum-profile-name-weight: 700;
    --forum-profile-name-text-shadow: 0 1px 2px rgba(0,0,0,0.15);
    --forum-profile-stats-bg: #ffffff;
    --forum-profile-stats-radius: 10px;
    --forum-profile-stats-padding: 14px;
    --forum-profile-stats-num-color: #ff8200;
    --forum-profile-stats-num-weight: 700;
    --forum-profile-stats-label-color: #999999;

    /* ===== 私信 ===== */
    --forum-message-item-bg: #ffffff;
    --forum-message-item-hover: #fff7f0;
    --forum-message-item-padding: 12px 14px;
    --forum-message-item-radius: 0;
    --forum-message-item-border: none;
    --forum-message-avatar-radius: 50%;
    --forum-message-avatar-size: 46px;
    --forum-message-avatar-ring: 0 1px 2px rgba(0,0,0,0.1);
    --forum-message-name-color: #333333;
    --forum-message-name-weight: 600;
    --forum-message-name-size: 15px;
    --forum-message-preview-color: #999999;
    --forum-message-preview-size: 13px;
    --forum-message-time-color: #bbbbbb;
    --forum-message-time-size: 11px;
    --forum-message-badge-bg: #ff3b30;
    --forum-message-badge-color: #ffffff;

    /* ===== 评论区 ===== */
    --forum-post-detail-bg: #ffffff;
    --forum-comments-bg: #ffffff;
    --forum-comments-header-color: #333333;
    --forum-comments-border-top: 8px solid #f5f5f5;
    --forum-comment-bg: transparent;
    --forum-comment-author-color: #eb7350;
    --forum-comment-author-weight: 600;
    --forum-comment-content-color: #333333;
    --forum-comment-content-size: 15px;
    --forum-comment-meta-color: #bbbbbb;
    --forum-comment-input-bar-bg: #ffffff;
    --forum-comment-input-bar-border: 1px solid #ececec;
    --forum-comment-input-bg: #f5f5f5;
    --forum-comment-input-color: #333333;
    --forum-comment-input-radius: 18px;

    /* ===== Tab ===== */
    --forum-tabs-bg: #ffffff;
    --forum-tabs-border: 1px solid #ececec;
    --forum-tab-color: #666666;
    --forum-tab-color-active: #ff8200;
    --forum-tab-weight-active: 700;
    --forum-tab-underline: #ff8200;
    --forum-tab-underline-height: 3px;

    /* ===== 字体 ===== */
    --forum-font-family: -apple-system, "Helvetica Neue", "PingFang SC", "Heiti SC", sans-serif;
    --forum-font-family-heading: -apple-system, "Helvetica Neue", "PingFang SC", "Heiti SC", sans-serif;
    --forum-font-family-mono: Menlo, Consolas, monospace;

    /* ===== 动画 ===== */
    --forum-card-transition: all 0.15s ease;
    --forum-card-hover-transform: none;
    --forum-card-active-transform: scale(0.98);
    --forum-fab-hover-transform: scale(1.08) translateY(-8px);
    --forum-fade-in-duration: 0.2s;

    /* ===== 滚动条 ===== */
    --forum-scrollbar-width: 6px;
    --forum-scrollbar-thumb-bg: rgba(0,0,0,0.2);
    --forum-scrollbar-thumb-radius: 3px;
    --forum-scrollbar-track-bg: transparent;
}


