/* 裝飾 */
.star { position: absolute; color: #c0c0c0; z-index: 10;}
.s1 { top: 12%; left: 16%; font-size: 20px; transform: rotate(-15deg); }
.s2 { top: 38%; left: 4%; font-size: 16px; color: #a0a0a0; transform: rotate(10deg); }
.s3 { top: 48%; left: 14%; font-size: 12px; color: #d0d0d0; }
.s4 { bottom: 35%; left: 10%; font-size: 22px; color: #cfcfcf; }
.s5 { bottom: 12%; right: 10%; font-size: 18px; color: #e6c5c8; /* 粉色星星 */ }
.music { position: absolute; bottom: 3%; right: 26%; font-size: 16px; color: #333; font-weight: bold; transform: rotate(15deg); z-index: 10; }

/* 照片通用樣式 */
.pic {
  width: 100%; height: 100%;
  background-color: #eee;
  background-size: cover;
  background-position: center;
  border: 1px solid rgba(0,0,0,0.05);
  border-radius: 1px;
}

/* 左側暗色照片 */
.pol-dark {
  position: absolute;
  top: 18%; left: 16%;
  width: 46%; height: 55%;
  padding: 4%; padding-bottom: 12%;
  box-shadow: 2px 4px 12px rgba(0,0,0,0.2);
  transform: rotate(-12deg);
  border: 1px solid #444;
  border-radius: 2px;
  z-index: 2;
  box-sizing: border-box;
}

/* 夾子前片 (Plastic Front Clamp) */
.clip-body {
  position: absolute; top: -5%; left: 35%;
  width: 30%; height: 10%;
  background: #fafafa;
  border-radius: 3px;
  box-shadow: 0 4px 6px rgba(0,0,0,0.1), inset 0 2px 3px rgba(255,255,255,1);
  border: 1px solid #dcdcdc;
  z-index: 5;
}

/* 轉軸 (Hinge) */
.clip-hole {
  position: absolute;
  top: -30%; left: 50%;
  transform: translateX(-50%);
  width: 12%; height: 60%;
  background: #d4d4d4;
  border-radius: 2px;
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.2), 0 2px 2px rgba(0,0,0,0.1);
  border: 1px solid #aaa;
  z-index: 6;
}

/* 金屬絲夾柄 (Wire Handles) */
.clip-wire {
  position: absolute; top: -16%;
  width: 10%; height: 16%;
  border: 2px solid #b0b0b0;
  border-bottom: none;
  border-radius: 6px 6px 0 0;
  z-index: 3;
  box-shadow: inset 0 1px 1px rgba(255,255,255,0.7);
  background: transparent;
  backdrop-filter: none;
}
.clip-wire::after, .clip-wire::before { display: none; }

.w1 { left: 40%; transform: rotate(-12deg); transform-origin: bottom center; }
.w2 { left: 50%; transform: rotate(12deg); transform-origin: bottom center; }

/* 右側亮色照片 */
.pol-light {
  position: absolute;
  bottom: 8%; right: 8%;
  width: 44%; height: 55%;
  background-color: #fff;
  padding: 3.5%; padding-bottom: 11%;
  box-shadow: -2px 6px 15px rgba(0,0,0,0.15);
  transform: rotate(8deg);
  border-radius: 2px;
  box-sizing: border-box;
  z-index: 5;
}

/* 氣泡對話框 */
.bubble {
  position: absolute;
  padding: 3px 7px;
  border-radius: 8px;
  font-size: 6px;
  font-weight: 700;
  box-shadow: 1px 3px 8px rgba(0,0,0,0.08);
  z-index: 10;
  white-space: nowrap;
}
.b-dark {
  top: 10%; right: 4%;
  background: #555; color: #fff;
}
/* 暗氣泡小尾巴 */
.b-dark::after {
  content: ''; position: absolute;
  bottom: -3px; right: 25%;
  border-width: 4px 4px 0 0; border-style: solid;
  border-color: #555 transparent transparent transparent;
}
.b-light {
  top: 24%; right: 9%;
  background: #fff; color: #555;
}
/* 亮氣泡小尾巴 */
.b-light::after {
  content: ''; position: absolute;
  top: -3px; left: 20%;
  border-width: 0 0 4px 4px; border-style: solid;
  border-color: transparent transparent #fff transparent;
}

