/* 夜间/中 — nuojiji messaging app theme */

/* =============================================== Theme: iOS 原生短信风 (极简韩系夜间 + 终极玻璃质感) Style: 暗黑曜石 3D 气泡 / 舒展玻璃顶栏 / 纯白黑白灰底栏 ================================================ */

:root {
  /* 📱 手机适配：顶栏整体高度 */
  --top-header-height: 118px;

  /* ======================================= 📝 文本自定义区 (随时在这里修改文字即可) ======================================= */
  /* 1. 顶栏与搜索文字 */
  --nav-left-text: "编辑";
  --nav-title-text: "信息";
  --search-text: "搜索";

  /* 2. 底栏第一项 */
  --tab1-en: "WeChat";
  --tab1-zh: "微信";

  /* 3. 底栏第二项 */
  --tab2-en: "Favs";
  --tab2-zh: "收藏";

  /* 4. 底栏第三项 */
  --tab3-en: "Moments";
  --tab3-zh: "朋友圈";

  /* 5. 底栏第四项 */
  --tab4-en: "Me";
  --tab4-zh: "我";
}

/* ─── 🌙 1. 全局：严格隔离，纯粹夜间模式 ─── */
#messaging-chat-tab {
  background-color: #000000 !important;

  /* 💥 恢复夜间专属深色壁纸 */
