  --nj-msg-bg-image-size: cover !important;
  --nj-msg-bg-image-position: center !important;

  --nj-msg-bg: transparent !important;
  --nj-msg-text: #ffffff !important;
  --nj-msg-text-muted: #98989d !important;
  --nj-msg-text-time: #98989d !important;

  --nj-msg-card-bg: transparent !important;
  --nj-msg-card-bg-pinned: transparent !important;
  --nj-msg-card-border: none !important;
  --nj-msg-card-radius: 0px !important;
  --nj-msg-card-gap: 0px !important;
  --nj-msg-card-padding: 0px !important;
  --nj-msg-avatar-shadow: none !important;

  background-image: var(--nj-msg-bg-image) !important;
  background-size: cover !important;
  background-position: center !important;
  overflow-x: hidden !important;
  width: 100% !important;
  box-sizing: border-box !important;
}

/* ─── 🍎 2. 完美 iOS 顶栏 (暗色空气玻璃气泡) ─── */
.nj-chat-tab-header {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-bottom: 0.5px solid rgba(255, 255, 255, 0.15) !important;
  box-shadow: none !important;

  padding: calc(24px + var(--nuo-safe-top)) 24px 16px 24px !important;
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;

  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  box-sizing: border-box !important;
  z-index: 9999 !important;
  pointer-events: none !important;
}

.nj-chat-tab-header-back,
.nj-chat-tab-header-title-btn,
.nj-chat-tab-header-edit {
  pointer-events: auto !important;
}

.nj-chat-tab-header::after,
.nj-chat-tab-header::before,
.nj-chat-tab-header-title {
  display: none !important;
  content: none !important;
}

/* 💥 左侧：夜间 37px 药丸玻璃气泡 (调用顶栏变量) */
.nj-chat-tab-header-back {
  flex: 0 0 auto !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;

  background: rgba(255, 255, 255, 0.15) !important;
  backdrop-filter: blur(20px) saturate(150%) !important;
