}

/* 顶栏 */
[data-color-scheme="dark"] .nj-chat-tab-header {
    background: rgba(26, 25, 30, 0.95) !important;
    border-bottom-color: #1a1a1e !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header-back::before,
[data-color-scheme="dark"] .nj-chat-tab-header-title-btn::before,
