}

/* 搜索框自定义文字颜色 */
[data-color-scheme="dark"] .nj-chat-tab-search::after {
    color: #888 !important;
}

/* 聊天卡片背景 */
[data-color-scheme="dark"] .nj-chat-item {
    background: rgba(40, 40, 45, 0.9) !important;
}
[data-color-scheme="dark"] .nj-chat-item-name,
[data-color-scheme="dark"] .nj-chat-item-preview,
[data-color-scheme="dark"] .nj-chat-item-time {
    color: #e0e0e0 !important;
}
[data-color-scheme="dark"] .nj-chat-item-preview {
    color: #aaa !important;
}
[data-color-scheme="dark"] .nj-chat-item-time {
    color: #888 !important;
}

/* 名称前图床（普通组与置顶组）—— 保持原图，若原图深色需调整滤镜，这里不变 */
/* 名称后图标 —— 不变，由用户自备图床决定 */

/* 头像装饰层（不变） */

/* 便签头像边框颜色调亮一点 */
[data-color-scheme="dark"] .nj-chat-tab-note-avatar {
    border: 1.9px solid #888 !important;
}

/* 四张装饰图片的白色边框保留，不覆盖 */

/* 单词区域（Chats Friends Groups） */
[data-color-scheme="dark"] .nj-chat-tab-list::before {
    color: #e0e0e0 !important;
    border-bottom-color: #e0e0e0 !important;
}
[data-color-scheme="dark"] .nj-chat-tab-list::after {
    color: #aaa !important;
}

/* 底栏悬浮胶囊 */
[data-color-scheme="dark"] .nj-tab-bottom-bar {
    background: rgba(40, 40, 45, 0.85) !important;
    border: 1px solid rgba(255, 255, 255, 0.1) !important;
    box-shadow: 0 -2px 12px rgba(0, 0, 0, 0.2) !important;
}

/* 底栏文字和图标（通过滤镜反色或调整亮度） */
[data-color-scheme="dark"] .nj-tab-bottom-icon {
    filter: brightness(0) invert(1) !important;
    opacity: 0.8 !important;
}
[data-color-scheme="dark"] .nj-tab-bottom-item-active .nj-tab-bottom-icon {
    opacity: 1 !important;
}
[data-color-scheme="dark"] .nj-tab-bottom-item::after {
    color: #aaa !important;
}
[data-color-scheme="dark"] .nj-tab-bottom-item-active::after {
    color: #fff !important;
}

/* 底栏未读角标背景（已在日间设为蓝色，夜间保留蓝色，可微调） */
[data-color-scheme="dark"] .nj-tab-bottom-total-unread,
[data-color-scheme="dark"] .nj-tab-bottom-moments-dot {
    background-color: #0F80E6 !important; /* 保持蓝色，也可改为 #3b8fe6 */
}

/* 未读角标文字和背景（日间蓝色，夜间可稍亮） */
[data-color-scheme="dark"] .nj-chat-item-unread-badge,
[data-color-scheme="dark"] .nj-chat-item [class*="unread"],
[data-color-scheme="dark"] .nj-chat-item [class*="badge"] {
    background-color: #3b8fe6 !important;
}

/* 滚动条暗色 */
[data-color-scheme="dark"] ::-webkit-scrollbar {
    background-color: #1a1a1e;
}
[data-color-scheme="dark"] ::-webkit-scrollbar-thumb {
    background-color: #3a3a3e;
    border-radius: 10px;
}

[data-color-scheme="dark"] .nj-chat-item:not(.nj-chat-item-pinned) .nj-chat-item-name::after {
    background-image: var(--name-after-ordinary-dark) !important;
}

[data-color-scheme="dark"] .nj-chat-item-pinned .nj-chat-item-name::after {
    background-image: var(--name-after-pinned-dark) !important;
    width: 40px !important;   /* 改为您需要的大小 */
    height: 40px !important;
}
[data-color-scheme="dark"] .nj-chat-item-pinned .nj-chat-item-name::after {
    /* 调整 right 值：增大则图标向左移动，减小则向右移动 */
    right: -5px !important;
}

/* 夜间模式：顶栏字母颜色白色 + 右上角图标反白（如之前未写则加上） */
[data-color-scheme="dark"] .nj-chat-tab-header-back::before,
[data-color-scheme="dark"] .nj-chat-tab-header-title-btn::before,
[data-color-scheme="dark"] .nj-chat-tab-header-title-btn::after {
    color: #ffffff !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header-edit {
    filter: brightness(0) invert(1) !important;
}

