    content: '' !important;
    position: absolute !important;

    /* 这是一个扩大的隐形点击热区，图标画在这个热区内 */
    left: -50px !important; top: -8px !important;
    width: 200px !important; height: 50px !important;
    z-index: 60 !important;

    /* 填入左侧图标URL */
    background-image: url("https://i.postimg.cc/TP145szK/IMG-5161.png") !important;

    /* 🔧【左侧图标大小调整】 */
    /* 现在的 36px 是图标的宽高，改大变大，改小变小 */
    background-size: 30px !important; 

    /* 🔧【左侧图标位置调整】 */
    /* left 6px 表示距离左边6px (改大往右，改小往左) */
    /* center 表示垂直居中 (如果想微调上下，可以改成比如 10px 或 20px) */
    background-position: left 6px center !important; 
    background-repeat: no-repeat !important;
}

/* 🌟 右侧三个图标 (爱心、点赞、分享) */
.xt-text:nth-of-type(4)::after {
    content: '' !important; 
    position: absolute !important;

    /* 🔧【右侧三个图标整体位置调整】 */
    /* left: 185px 表示整体距离输入框左侧的距离 (改大整体往右，改小整体往左) */
    left: 185px !important; 
    /* top: 6px 表示整体上下偏移 (负数往上，正数往下) */
    top: 6px !important;    

    /* 🔧【右侧图标区域总宽度】 */
    /* 如果你觉得三个图标挤在一起了，就把 100px 改大 (比如 120px) */
    width: 110px !important; 
    height: 26px !important; 

    /* 填入三张图片 */
    background-image: 
        url("https://i.postimg.cc/ZqnMvQGC/IMG-5162.png"), /* 第一个 */
        url("https://i.postimg.cc/xd84NZwd/IMG-5164.png"), /* 第二个 */
        url("https://i.postimg.cc/P527xHRv/IMG-5165.png")  /* 第三个 */
        !important;

    /* 🔧【三个图标各自的大小】 */
    /* 分别对应：第一个, 第二个, 第三个。现在的 24px 是宽高 */
    background-size: 26px, 26px, 26px !important; 

    /* 🔧【三个图标各自的排版位置】 */
    /* left: 靠左, center: 居中, right: 靠右 */
    /* 如果你想手动控制间距，可以写具体像素，比如: 0px center, 40px center, 80px center */
    background-position: 
        left center, 
        center center, 
        right center 
        !important;

    background-repeat: no-repeat !important;
    pointer-events: none !important;
}

/* ================= 6. 心声层 (Node 5) ================= */
.xt-text:nth-of-type(5) {
    display: inline !important; 
    position: relative !important;
    top: 280px !important; 
    left: 0px !important; 
    background-color: #000000 !important;
    color: #ffffff !important;
    font-size: 15px !important;
    font-weight: 500 !important;
    line-height: 2 !important; 
    padding: 6px 10px !important;
    border-radius: 4px !important;
    -webkit-box-decoration-break: clone !important;
    box-decoration-break: clone !important;
    text-align: left !important;
    white-space: pre-wrap !important;
    word-break: break-word !important;
    z-index: 40 !important;
    pointer-events: none !important; 
    opacity: 0 !important;
    transition: opacity 0.2s ease !important;
}
.xt-root:active .xt-text:nth-of-type(5),
.xt-root:hover .xt-text:nth-of-type(5) {
    opacity: 1 !important;
}
.xt-text:nth-of-type(4):active ~ .xt-text:nth-of-type(5),
.xt-text:nth-of-type(4):hover ~ .xt-text:nth-of-type(5) {
    opacity: 0 !important; visibility: hidden !important;
}

/* ================= 7. 层叠推拽弹幕 (Node 6-9) ================= */
.xt-text:nth-of-type(n+6) {
    position: absolute !important;
    left: 65px !important; 
    width: fit-content !important; 
    max-width: 250px !important;
    padding: 8px 12px !important;
    font-size: 13px !important;
    font-weight: 500 !important;
    line-height: 1.5 !important;
    word-break: break-word !important;

    background: rgba(40, 35, 35, 0.45) !important;
    backdrop-filter: blur(10px) !important; 
    -webkit-backdrop-filter: blur(10px) !important;
    border-radius: 4px 18px 18px 18px !important;

    color: #ffffff !important;
    pointer-events: none !important;

    opacity: 0 !important;
    transform: translateY(20px) !important;
    z-index: 60 !important;
    transition: opacity 0.3s ease, transform 0.5s ease !important;
}

.xt-text:nth-of-type(6) { bottom: 275px !important; }
.xt-text:nth-of-type(7) { bottom: 205px !important; }
.xt-text:nth-of-type(8) { bottom: 135px !important; }
.xt-text:nth-of-type(9) { bottom: 75px !important; background: rgba(22,22,22,0.9) !important; border-radius: 20px !important; }

.xt-text:nth-of-type(n+6)::first-line {
    color: rgba(255,255,255,0.7) !important;
    font-size: 11px !important;
    font-weight: 400 !important;
}

.xt-text:nth-of-type(n+6)::before {
    content: '' !important;
    position: absolute !important;
    left: -38px !important; top: 2px !important; 
    width: 30px !important; height: 30px !important;
    border-radius: 50% !important;
    border: 1px solid rgba(255,255,255,0.15) !important;
}

.xt-text:nth-of-type(6)::before { background: url('https://i.postimg.cc/nzyFPBKJ/IMG-5168.jpg') center/cover !important; }
.xt-text:nth-of-type(7)::before { background: url('https://i.postimg.cc/52sbBwTn/IMG-4804.jpg') center/cover !important; }
.xt-text:nth-of-type(8)::before { background: url('https://i.postimg.cc/gJmVCLGT/IMG-5184.jpg') center/cover !important; }
.xt-text:nth-of-type(9)::before { background: url('https://i.postimg.cc/x1mLq3CK/IMG-5185.jpg') center/cover !important; }

.xt-text:nth-of-type(4):active ~ .xt-text:nth-of-type(n+6),
.xt-text:nth-of-type(4):hover ~ .xt-text:nth-of-type(n+6),
.xt-text:nth-of-type(n+6):hover {
    opacity: 1 !important;
    transform: translateY(0) !important;
}

.xt-text:nth-of-type(4):hover ~ .xt-text:nth-of-type(6) { transition: opacity 0.5s ease 0s,   transform 0.6s cubic-bezier(0.1, 0.9, 0.2, 1) 0s   !important; }
.xt-text:nth-of-type(4):hover ~ .xt-text:nth-of-type(7) { transition: opacity 0.5s ease 0.1s, transform 0.6s cubic-bezier(0.1, 0.9, 0.2, 1) 0.1s !important; }
.xt-text:nth-of-type(4):hover ~ .xt-text:nth-of-type(8) { transition: opacity 0.5s ease 0.2s, transform 0.6s cubic-bezier(0.1, 0.9, 0.2, 1) 0.2s !important; }
.xt-text:nth-of-type(4):hover ~ .xt-text:nth-of-type(9) { transition: opacity 0.5s ease 0.3s, transform 0.6s cubic-bezier(0.1, 0.9, 0.2, 1) 0.3s !important; }

