value.customCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&display=swap');

/* ══════════════════════
   ROOT
══════════════════════ */
.xt-root {
  --xt-bg:         #fafafa;
  --xt-text:       #1a1a1a;
  --xt-text-sub:   #737373;
  --xt-text-muted: #999999;
  --xt-accent:     #4d4d4d;
  --xt-accent-bg:  rgba(0,0,0,0.08);
  --xt-border:     #dcdcdc;
  --xt-radius:     18px;
  --xt-radius-sm:  11px;
  --xt-font:       'Noto Sans SC','PingFang SC','Hiragino Sans GB',sans-serif;
  --xt-anim-duration: 0.28s;
  --pink:          #4d4d4d;
  --pink-bg:       #f5f5f5;
  --pink-border:   #dcdcdc;
  --pink-text:     #333333;
  background: var(--xt-bg);
  padding: 0;
  font-size: 13px;
  line-height: 1.5;
}
.xt-content { padding: 14px 13px 14px; }

/* ══════════════════════
   CARD 通用
══════════════════════ */
.xt-card {
  background: #ffffff !important;
  border: 1.5px solid #e3e3e3 !important;
  border-radius: 16px !important;
  padding: 0 !important;
  margin-bottom: 10px !important;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06) !important;
  overflow: hidden !important;
}
.xt-card:hover { box-shadow: 0 4px 18px rgba(0,0,0,0.10) !important; transform: none !important; }
.xt-card-title {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #999999 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  padding: 11px 14px 2px !important;
  margin: 0 !important;
  display: block !important;
}

/* ══════════════════════
   最近搜索区
   设计：带标题的独立白卡
   四行搜索词 + 展开心声
══════════════════════ */

/* 四个搜索词共同外包一个白卡效果
   用 search1 第一行的 ::before 做卡片标题 */
.xt-text-search1 {
  margin-top: 0 !important;
  border-radius: 16px 16px 0 0 !important;
  border-bottom: 1px solid #f0f0f0 !important;
  padding-top: 10px !important;
}
.xt-text-search1::before {
  content: "🔍  最近搜索" !important;
  display: block !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #999999 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  margin-bottom: 8px !important;
  padding: 0 !important;
}

/* 四个搜索词的共同样式 */
.xt-text-search1,
.xt-text-search2,
.xt-text-search3,
.xt-text-search4 {
  display: block !important;
  background: #ffffff !important;
  border-left: 1.5px solid #e3e3e3 !important;
  border-right: 1.5px solid #e3e3e3 !important;
  border-top: none !important;
  border-bottom: 1px solid #f0f0f0 !important;
  border-radius: 0 !important;
  padding: 11px 40px 11px 16px !important;
  margin: 0 !important;
  font-size: 13.5px !important;
  font-weight: 400 !important;
  color: #1a1a1a !important;
  font-style: normal !important;
  cursor: pointer !important;
  position: relative !important;
  transition: background 0.15s !important;
}
/* 左侧搜索图标 */
.xt-text-search1::after,
.xt-text-search2::after,
.xt-text-search3::after,
.xt-text-search4::after {
  content: "›" !important;
  position: absolute !important;
  right: 15px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 20px !important;
  color: #c2c2c2 !important;
  line-height: 1 !important;
  transition: color 0.15s, transform 0.2s !important;
  font-style: normal !important;
}
/* 最后一行圆角收尾（无心声展开时） */
.xt-text-search4 {
  border-radius: 0 0 16px 16px !important;
  border-bottom: 1.5px solid #e3e3e3 !important;
  margin-bottom: 10px !important;
}
/* 展开时最后一行取消圆角，由OS气泡接管 */
#xt-t4:checked ~ .xt-content .xt-text-search4 {
  border-radius: 0 !important;
  border-bottom: 1px solid #f0f0f0 !important;
}

/* 选中状态高亮 */
#xt-t1:checked ~ .xt-content .xt-text-search1 { background: #f0f0f0 !important; color: #000000 !important; }
#xt-t2:checked ~ .xt-content .xt-text-search2 { background: #f0f0f0 !important; color: #000000 !important; }
#xt-t3:checked ~ .xt-content .xt-text-search3 { background: #f0f0f0 !important; color: #000000 !important; }
#xt-t4:checked ~ .xt-content .xt-text-search4 { background: #f0f0f0 !important; color: #000000 !important; }
#xt-t1:checked ~ .xt-content .xt-text-search1::after { color: #4d4d4d !important; transform: translateY(-50%) rotate(90deg) !important; }
#xt-t2:checked ~ .xt-content .xt-text-search2::after { color: #4d4d4d !important; transform: translateY(-50%) rotate(90deg) !important; }
#xt-t3:checked ~ .xt-content .xt-text-search3::after { color: #4d4d4d !important; transform: translateY(-50%) rotate(90deg) !important; }
#xt-t4:checked ~ .xt-content .xt-text-search4::after { color: #4d4d4d !important; transform: translateY(-50%) rotate(90deg) !important; }

/* 搜索心声气泡 */
.xt-text-search1Os,
.xt-text-search2Os,
.xt-text-search3Os,
.xt-text-search4Os {
  display: block !important;
  max-height: 0 !important;
  overflow: hidden !important;
  background: #fafafa !important;
  border-left: 1.5px solid #e3e3e3 !important;
  border-right: 1.5px solid #e3e3e3 !important;
  border-top: none !important;
  border-bottom: none !important;
  border-radius: 0 !important;
  padding: 0 16px !important;
  margin: 0 !important;
  font-size: 12.5px !important;
  color: #595959 !important;
  font-style: italic !important;
  line-height: 1.75 !important;
  transition: max-height 0.3s ease, padding 0.22s ease !important;
}
/* search4的Os展开后需要有底部圆角 */
.xt-text-search4Os {
  border-radius: 0 0 16px 16px !important;
  border-bottom: 1.5px solid #e3e3e3 !important;
  margin-bottom: 10px !important;
}
#xt-t1:checked ~ .xt-content .xt-text-search1Os { max-height: 100px !important; padding: 10px 16px 12px !important; }
#xt-t2:checked ~ .xt-content .xt-text-search2Os { max-height: 100px !important; padding: 10px 16px 12px !important; }
#xt-t3:checked ~ .xt-content .xt-text-search3Os { max-height: 100px !important; padding: 10px 16px 12px !important; }
#xt-t4:checked ~ .xt-content .xt-text-search4Os { max-height: 100px !important; padding: 10px 16px 12px !important; }

/* 透明按钮覆盖搜索词行 */
.xt-action-1,.xt-action-2,.xt-action-3,.xt-action-4 {
  display: block !important;
  width: 100% !important;
  height: 44px !important;
  margin: -44px 0 0 0 !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  cursor: pointer !important;
  position: relative !important;
  z-index: 5 !important;
  opacity: 0 !important;
  font-size: 0 !important;
}
.xt-action-1::after,.xt-action-2::after,
.xt-action-3::after,.xt-action-4::after { content: "" !important; }

/* ══════════════════════
   ROW 两列
══════════════════════ */
.xt-row { gap: 9px !important; margin-bottom: 10px !important; align-items: stretch !important; }
.xt-row > * { margin-bottom: 0 !important; }

/* ── 动物塑 */
.xt-text-animalType {
  display: block !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #4d4d4d !important;
  letter-spacing: 0.8px !important;
  font-style: normal !important;
  padding: 5px 13px 2px !important;
  background: transparent !important;
  border: none !important;
  text-transform: uppercase !important;
}
.xt-text-animalAct {
  display: block !important;
  font-size: 12.5px !important;
  color: #1a1a1a !important;
  font-style: normal !important;
  line-height: 1.8 !important;
  padding: 0 13px 13px !important;
  background: transparent !important;
  border: none !important;
}

/* ── 待办 */
.xt-list { background: transparent !important; padding: 5px 0 8px !important; margin: 0 !important; border-radius: 0 !important; }
.xt-list-item {
  display: flex !important; align-items: center !important; gap: 9px !important;
