.xt-list-text { font-size: 12.5px !important; color: #1a1a1a !important; font-style: normal !important; }

/* ══════════════════════
   日记横格纸
══════════════════════ */
.xt-quote {
  background: repeating-linear-gradient(
    to bottom,
    transparent 0, transparent 23px,
    #e0e0e0 23px, #e0e0e0 24px
  ) !important;
  border: none !important;
  border-radius: 0 0 14px 14px !important;
  padding: 8px 15px 14px !important;
  margin: 0 !important;
  font-size: 13px !important;
  color: #1a1a1a !important;
  line-height: 24px !important;
  font-style: normal !important;
  box-shadow: none !important;
  min-height: 120px !important;
}
.xt-quote::before,.xt-quote::after { display: none !important; content: none !important; }

/* ══════════════════════
   🔞 浏览历史区
   设计：独立白卡 + 信息流
   平台标签(小) + 标题(大) + OS气泡
══════════════════════ */

/* 整体区域：第一个tag上方加标题 */
.xt-text-nsfw1Tag {
  margin-top: 0 !important;
  border-radius: 16px 16px 0 0 !important;
}
.xt-text-nsfw1Tag::before {
